import java.io.*;

public class B {
    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner();
        long R = in.nextLong();
        long C = in.nextLong();
        out.println(solve(Math.min(R, C), Math.max(R, C)));
        out.close();
    }

    static long solve(long r, long c) {
        if (r < 3 && c < 3) return 0L;
        if (r == 1) return oneRow(c);
        if (r == 2) {
            if (c == 3 || c == 7) return 2L * (c - 1);
            return 2L * c;
        }
        long total = r * c;
        return (total & 1L) == 0L ? total : total - 1L;
    }

    private static long oneRow(long c) {
        long m = c % 6;
        long adj;
        if (m <= 3 && m != 0) {
            adj = m;
        } else if (m == 4) {
            adj = 2;
        } else if (m == 5) {
            adj = 1;
        } else {
            adj = 0;
        }
        return c - adj;
    }

    static class FastScanner {
        private int read() throws IOException {
            return System.in.read();
        }

        private boolean space(int b) {
            return b == -1 || b == ' ' || b == '\t' || b == '\n' || b == '\r' || b == '\f';
        }

        String next() throws IOException {
            int b;
            while ((b = read()) != -1 && space(b)) {}
            if (b == -1) throw null;
            StringBuilder sb = new StringBuilder();
            while (b != -1 && !space(b)) {
                sb.append((char) b);
                b = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
